            sh:description "The chosen repository's name, as the pinned re3data export gives it." ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:Literal ;
            sh:order 0 ;
            sh:path dd:chosen_repository_name ] ;
    sh:targetClass dd:ChosenRepository .

